bool SoundSubsystem::play_cd_track(uint32_t track, uint32_t option) {
    if (!cd_audio_open_ || !cd_audio_hooks_.status ||
        !cd_audio_hooks_.play) {
        return false;
    }
    // 0x004994A0 queries MCI status item 7 before starting playback.
    const CdAudioQuery status = cd_audio_hooks_.status(7);
    if (!status.command_succeeded || status.value == 0) {
        return false;
    }
    const bool played = cd_audio_hooks_.play(track & 0xFFU, option);
    last_cd_track_ = track;
    return played;
}
